// 样式
const styles = `
<style id="village-card-styles">
/* ==================== 全局动画 ==================== */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

@keyframes shimmer {
    0%, 100% { opacity: 0.5; }
    50% { opacity: 1; }
}

@keyframes heartbeat-dash-anim {
    72.5% {
        opacity: 0;
    }
    to {
        stroke-dashoffset: 0;
    }
}

/* ==================== 容器样式 ==================== */
.village-card-container {
    position: fixed;
    top: var(--topBarBlockSize, 60px);
    left: 0;
    max-width: 1200px;
    display: flex;
    flex-direction: column;
    gap: 0;
    z-index: 500;
    color: #e8dcc8;
    font-family: 'Microsoft YaHei', 'SimHei', Arial, sans-serif;
    padding: 0;
    width: auto;
    cursor: default;
    user-select: none;
    -webkit-user-select: none;
    touch-action: none;
    -webkit-touch-callout: none;
    padding:20px;
    max-width: 500px;
}

.village-card-container.dragging {
    opacity: 0.85;
    cursor: grabbing !important;
    z-index: 999;
    user-select: none !important;
    -webkit-user-select: none !important;
}

/* 卡片内容区域 */
.village-card-content-inner {
    cursor: default;
    user-select: auto;
    -webkit-user-select: auto;
    touch-action: auto;
}

/* 所有按钮和交互元素 - 绝对优先级 */
.village-card-container button,
.village-card-container button *,
.village-card-container .village-tab,
.village-card-container .village-tab *,
.village-card-container a,
.village-card-container a *,
.village-card-container select,
.village-card-container .bond-item {
    cursor: pointer !important;
    pointer-events: auto !important;
}

.village-card-container input,
.village-card-container textarea {
    cursor: text !important;
    pointer-events: auto !important;
}

/* ==================== 顶部状态区 ==================== */
.village-status-top {
    padding: 20px;
    text-align: center;
    background: linear-gradient(135deg, #1a1f2e 0%, #252b3d 100%);
    border: 2px solid #d4af37;
    border-radius: 8px;
    pointer-events: auto;
    position: relative;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6), 
                0 0 20px rgba(212, 175, 55, 0.2);
}

.village-status-top.hidden {
    display: none;
}

/* ==================== 卡片主体 ==================== */
.village-card-wrapper {
    margin-bottom: 0;
    perspective: 1000px;
    animation: fadeIn 0.5s ease-out backwards;
    position: relative;
    z-index: 2;
    pointer-events: auto;
    width: 100%;
}

.village-card-3d {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
}

.village-card-main {
    position: relative;
    width: 100%;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    pointer-events: auto;
}

/* ==================== 样式1 - 游戏风格主题 ==================== */
#village-card-status[data-style="style1"] .village-card-3d {
    width: 100%;
    max-width: 1200px;
}

#village-card-status[data-style="style1"] .village-card-main {
    background: linear-gradient(135deg, #1a1f2e 0%, #252b3d 100%);
    border: 3px solid #d4af37;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.8),
                0 0 30px rgba(212, 175, 55, 0.15),
                inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* ==================== 样式2 - 预留 ==================== */
#village-card-status[data-style="style2"] .village-card-3d {
    width: 100%;
    max-width: 1200px;
}

#village-card-status[data-style="style2"] .village-card-main {
    /* 样式2暂时不写 */
    background: linear-gradient(135deg, #4a3f35 0%, #3d3428 100%);
    border: 2px solid #5c4d3d;
}

/* ==================== 卡片内容 ==================== */
.village-card-content-inner {
    width: 100%;
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 0;
    overflow: hidden;
}

/* ==================== 控制按钮 ==================== */
.village-card-control-buttons {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    margin-bottom: 15px;
    padding-bottom: 15px;
    border-bottom: 2px solid rgba(212, 175, 55, 0.2);
}

.village-card-control-left {
    display: flex;
    gap: 8px;
    pointer-events: auto;
}

.village-card-control-right {
    display: flex;
    gap: 8px;
    margin-left: auto;
    pointer-events: auto;
}

.village-card-style-btn,
.village-card-refresh-btn,
.village-card-collapse-btn {
    width: 36px;
    height: 36px;
    padding: 0;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.15) 0%, rgba(212, 175, 55, 0.05) 100%);
    border: 2px solid rgba(212, 175, 55, 0.6);
    border-radius: 6px;
    color: #d4af37;
    cursor: pointer !important;
    font-size: 16px;
    transition: all 0.3s;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}



/* 按钮内的子元素（如 span）不拦截点击事件，让点击传递到按钮本身 */
.village-card-style-btn > *,
.village-card-refresh-btn > *,
.village-card-collapse-btn > * {
    pointer-events: none; /* 让点击穿透到按钮 */
    cursor: inherit;
}



.village-card-refresh-btn.refreshing {
    pointer-events: none;
    opacity: 0.6;
}

.village-card-refresh-btn.refreshing .icon {
    animation: spin 1s linear infinite;
}

/* 收起状态 */
.village-card-wrapper.collapsed {
    width: 38px;
    height: 38px;
}

.village-card-wrapper.collapsed .village-card-3d {
    width: 38px;
    max-width: 38px;
}

.village-card-wrapper.collapsed .village-card-content-inner > *:not(.village-card-control-buttons) {
    display: none;
}

.village-card-wrapper.collapsed .village-card-control-right {
    display: none;
}

.village-card-wrapper.collapsed .village-card-control-buttons {
    margin-bottom: 0;
    padding: 0;
    border: none;
}

.village-card-wrapper.collapsed .village-card-control-left {
    margin: 0;
}

.village-card-wrapper.collapsed .village-card-content-inner {
    padding: 0;
    width: 36px;
    height: 36px;
}

.village-card-wrapper.collapsed .village-card-main {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
    border-radius: 8px;
}

.village-card-wrapper.collapsed .village-card-collapse-btn {
    margin: 0;
}

/* ==================== Tab标签栏 ==================== */
.village-tabs {
    display: flex;
    gap: 8px;
    margin-bottom: 15px;
    flex-wrap: wrap;
    border-radius: 8px;
}

.village-tab {
    padding: 8px 16px;
    background: linear-gradient(135deg, rgba(26, 31, 46, 0.6) 0%, rgba(37, 43, 61, 0.6) 100%);
    border: 2px solid rgba(212, 175, 55, 0.3);
    border-radius: 6px;
    color: #a8a8a8;
    cursor: pointer;
    transition: all 0.3s;
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
    display: flex;
    align-items: center;
    gap: 6px;
}

.village-tab:hover {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.15) 0%, rgba(212, 175, 55, 0.05) 100%);
    border-color: rgba(212, 175, 55, 0.6);
    color: #d4af37;
    box-shadow: 0 2px 8px rgba(212, 175, 55, 0.2);
}

.village-tab.active {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.25) 0%, rgba(212, 175, 55, 0.15) 100%);
    border-color: #d4af37;
    color: #d4af37;
    box-shadow: 0 4px 12px rgba(212, 175, 55, 0.4),
                inset 0 1px 0 rgba(255, 255, 255, 0.1);
    font-weight: 600;
}

/* ==================== Tab内容区域 ==================== */
.village-tab-content {
    position: relative;
    max-height: 55vh;
    overflow-y: auto;
    overflow-x: hidden;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
}

.village-tab-content::-webkit-scrollbar {
    width: 8px;
}

.village-tab-content::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.4);
    border-radius: 4px;
}

.village-tab-content::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #d4af37 0%, #b8941f 100%);
    border-radius: 4px;
    box-shadow: 0 0 8px rgba(212, 175, 55, 0.4);
}

.village-tab-content::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #e5c158 0%, #d4af37 100%);
}

.village-panel-wrapper {
    display: none;
}

.village-panel-wrapper.active {
    display: block;
    animation: fadeIn 0.3s ease-out;
}

/* ==================== 从原城中村样式继承的面板样式 ==================== */
/* 这些样式保持原有的城中村面板样式 */

.section {
    background: linear-gradient(135deg, #1e2333 0%, #252b3d 100%);
    border: 2px solid rgba(212, 175, 55, 0.3);
    border-radius: 8px;
    margin-bottom: 15px;
    overflow: hidden;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5),
                inset 0 1px 0 rgba(255, 255, 255, 0.05);
    position: relative;
}

.section::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(circle at 20% 30%, rgba(212, 175, 55, 0.03) 0%, transparent 50%);
    pointer-events: none;
    border-radius: 8px;
}

.section-title {
    padding: 12px 16px;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.15) 0%, rgba(212, 175, 55, 0.05) 100%);
    border-bottom: 2px solid rgba(212, 175, 55, 0.3);
    font-size: 14px;
    font-weight: 600;
    color: #d4af37;
    display: flex;
    align-items: center;
    gap: 8px;
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.section-content {
    padding: 16px;
}

/* 世界信息栏 */
.world-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
}

.world-item {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.08) 0%, rgba(212, 175, 55, 0.03) 100%);
    border: 1px solid rgba(212, 175, 55, 0.2);
    border-radius: 6px;
    font-size: 13px;
}

.world-label {
    color: #a8a8a8;
    font-size: 12px;
}

.world-value {
    color: #e5c158;
    font-weight: 600;
}

/* 互动角色状态 */
.interaction-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 12px;
}

.character-item {
    padding: 12px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    border-left: 3px solid rgba(74, 158, 255, 0.5);
}

.character-name {
    font-weight: 600;
    color: #4a9eff;
    margin-bottom: 8px;
    font-size: 14px;
}

.character-status {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 12px;
}

.status-row {
    display: flex;
    justify-content: flex-start;
    align-items: flex-start;
}

.status-label {
    color: #a8a8a8;
    margin-right: 6px;
}

.status-value {
    color: #e5c158;
}


/* 我的信息 */
.my-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
    margin-bottom: 16px;
}

.my-info-item {
    padding: 12px;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.08) 0%, rgba(212, 175, 55, 0.03) 100%);
    border-radius: 6px;
    text-align: center;
    border: 1px solid rgba(212, 175, 55, 0.3);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
}

.my-info-label {
    color: #a8a8a8;
    font-size: 11px;
    margin-bottom: 6px;
}

.my-info-value {
    color: #e5c158;
    font-weight: 600;
    font-size: 16px;
}

.my-info-unit {
    color: #a8a8a8;
    font-size: 11px;
    margin-left: 2px;
}

.title-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 16px;
}

.title-badge {
    padding: 6px 12px;
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.25) 0%, rgba(212, 175, 55, 0.15) 100%);
    border: 1px solid rgba(212, 175, 55, 0.5);
    border-radius: 12px;
    color: #d4af37;
    font-size: 12px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 4px;
    box-shadow: 0 2px 6px rgba(212, 175, 55, 0.2);
}

.modification-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 10px;
}

.modification-item {
    padding: 10px 12px;
    background: rgba(218, 165, 32, 0.1);
    border-radius: 8px;
    border-left: 3px solid #daa520;
    font-size: 12px;
    color: #5d4e37;
    display: flex;
    align-items: center;
    gap: 6px;
}

/* 黑市 */
.service-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
}

.service-item {
    padding: 14px;
    background: linear-gradient(135deg, rgba(26, 31, 46, 0.6) 0%, rgba(37, 43, 61, 0.6) 100%);
    border-radius: 8px;
    border: 2px solid rgba(212, 175, 55, 0.3);
    transition: all 0.3s;
    cursor: pointer;
    position: relative;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.service-item:hover {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.15) 0%, rgba(212, 175, 55, 0.05) 100%);
    border-color: #d4af37;
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(212, 175, 55, 0.3);
}

.service-item.purchased {
    border-color: rgba(76, 175, 80, 0.5);
    background: rgba(76, 175, 80, 0.05);
}

.service-item.purchased::before {
    content: '✓';
    position: absolute;
    top: 8px;
    right: 8px;
    background: rgba(76, 175, 80, 0.8);
    color: white;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: bold;
}

.service-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 10px;
    gap: 10px;
}

.service-name {
    font-weight: 600;
    color: #e5c158;
    font-size: 14px;
    flex: 1;
}

.service-price {
    background: linear-gradient(135deg, rgba(139, 115, 85, 0.3) 0%, rgba(122, 107, 93, 0.3) 100%);
    padding: 4px 10px;
    border-radius: 12px;
    color: #d4af82;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
}

.service-effect {
    padding: 8px 10px;
    background: rgba(139, 115, 85, 0.2);
    border-radius: 6px;
    color: #c9b89a;
    font-size: 12px;
    font-weight: 500;
    margin-bottom: 8px;
    display: inline-block;
}

.service-description {
    color: #c9b89a;
    font-size: 11px;
    line-height: 1.6;
}

/* 道具 */
.item-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 12px;
}

.item-card {
    padding: 12px;
    background: linear-gradient(135deg, rgba(26, 31, 46, 0.6) 0%, rgba(37, 43, 61, 0.6) 100%);
    border-radius: 8px;
    border: 2px solid rgba(212, 175, 55, 0.3);
    transition: all 0.3s;
    position: relative;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.item-card:hover {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.12) 0%, rgba(212, 175, 55, 0.04) 100%);
    border-color: rgba(212, 175, 55, 0.6);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(212, 175, 55, 0.2);
}

.item-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
}

.item-name {
    font-weight: 600;
    color: #e5c158;
    font-size: 13px;
    flex: 1;
}

.item-count {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.25) 0%, rgba(212, 175, 55, 0.15) 100%);
    padding: 3px 10px;
    border-radius: 12px;
    color: #d4af37;
    font-size: 12px;
    font-weight: 600;
    border: 1px solid rgba(212, 175, 55, 0.4);
}

.item-description {
    color: #c9b89a;
    font-size: 11px;
    line-height: 1.5;
}

/* 祈福订单 */
.order-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.order-item {
    padding: 14px;
    background: linear-gradient(135deg, rgba(26, 31, 46, 0.6) 0%, rgba(37, 43, 61, 0.6) 100%);
    border-radius: 8px;
    border: 2px solid rgba(212, 175, 55, 0.3);
    border-left: 4px solid #d4af37;
    transition: all 0.3s;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.order-item.completed {
    border-left-color: #7fb069;
    opacity: 0.75;
    border-color: rgba(127, 176, 105, 0.3);
}

.order-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 10px;
}

.order-client-name {
    font-weight: 600;
    color: #e5c158;
    font-size: 15px;
}

.order-status {
    padding: 4px 10px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 500;
}

.order-status.unaccepted {
    background: rgba(96, 165, 250, 0.2);
    color: #60a5fa;
}

.order-status.pending {
    background: rgba(255, 193, 7, 0.2);
    color: #ffc107;
}

.order-status.completed {
    background: rgba(76, 175, 80, 0.2);
    color: #4caf50;
}

.order-info {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
    font-size: 12px;
    margin-bottom: 10px;
}

.order-greeting {
    padding: 10px;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 6px;
    font-size: 12px;
    font-style: italic;
    color: #c9b89a;
    margin-top: 8px;
    border-left: 2px solid #8b7355;
}

.order-price {
    display: inline-block;
    padding: 6px 12px;
    background: linear-gradient(135deg, rgba(139, 115, 85, 0.3) 0%, rgba(122, 107, 93, 0.3) 100%);
    border-radius: 6px;
    color: #d4af82;
    font-weight: 600;
    font-size: 14px;
    margin-top: 8px;
}

/* 人物羁绊 */
.bond-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.bond-item {
    padding: 12px;
    background: linear-gradient(135deg, rgba(26, 31, 46, 0.6) 0%, rgba(37, 43, 61, 0.6) 100%);
    border-radius: 8px;
    border: 2px solid rgba(255, 107, 129, 0.3);
    border-left: 4px solid #ff6b81;
    cursor: pointer;
    transition: all 0.3s;
    position: relative;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

.bond-item:hover {
    background: linear-gradient(135deg, rgba(255, 107, 129, 0.1) 0%, rgba(255, 107, 129, 0.05) 100%);
    border-left-color: #ff8fa0;
    box-shadow: 0 4px 12px rgba(255, 107, 129, 0.2);
}

.bond-item::after {
    content: '▼';
    position: absolute;
    right: 12px;
    top: 12px;
    color: #a08464;
    font-size: 12px;
    transition: transform 0.3s;
}

.bond-item.collapsed::after {
    transform: rotate(-90deg);
}

.bond-item.collapsed .bond-details {
    display: none;
}

.bond-item.collapsed {
