    }
    $('#village-card-status').remove();
    $('#village-card-styles').remove();
    console.log('✅ 状态栏已清理');
}

// ==================== 全局函数暴露 ====================
if (typeof window !== 'undefined') {
    window.initializeVillageCardStatus = initializeVillageCardStatus;
