// ==================== 数据加载和显示 ====================
function loadAndDisplay(retryCount = 0) {
    console.log(`📥 开始加载MVU数据... (尝试 ${retryCount + 1})`);

    try {
        return _loadAndDisplayInternal(retryCount);
    } catch (error) {
        console.error('❌ loadAndDisplay 执行出错:', error);
        console.error('错误堆栈:', error.stack);

        $('#village-status-top').html(`
            <div style="color: #ef4444; padding: 15px;">
                <p style="margin-bottom: 10px;">❌ 加载数据时发生错误</p>
                <p style="font-size: 12px; margin-bottom: 10px; color: #9ca3af;">${error.message}</p>
                <button onclick="loadVillageCardDisplay(0)" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                    🔄 重试
                </button>
            </div>
        `).removeClass('hidden');

        // 不要移除旧卡片，保留已有内容
        return;
    }
}

function _loadAndDisplayInternal(retryCount = 0) {
    const mvuAvailable = typeof Mvu !== 'undefined' ||
                        typeof window.Mvu !== 'undefined' ||
                        (window.parent && typeof window.parent.Mvu !== 'undefined');

    if (!mvuAvailable) {
        console.warn(`⚠️ MVU框架未加载，尝试次数: ${retryCount + 1}`);

        if (retryCount < 3) {
            $('#village-status-top').html(`
                <div style="color: #60a5fa;">
                    <p>⏳ 等待MVU框架加载中... (${retryCount + 1}/3)</p>
                    <button onclick="diagnoseMvuAvailability()" style="margin-top: 10px; padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                        🔍 诊断MVU状态
                    </button>
                </div>
            `).removeClass('hidden');
            setTimeout(() => {
                loadAndDisplay(retryCount + 1);
            }, 2000);
        } else {
            $('#village-status-top').html(`
                <div style="color: #fbbf24;">
                    <p>⚠️ MVU框架未加载</p>
                    <p style="font-size: 12px; margin-top: 10px;">请先在聊天框运行相关初始化指令</p>
                    <div style="margin-top: 15px; display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;">
                        <button onclick="diagnoseMvuAvailability()" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                            🔍 诊断
                        </button>
                        <button onclick="loadVillageCardDisplay(0)" style="padding: 8px 16px; background: rgba(96, 165, 250, 0.2); border: 1px solid #60a5fa; border-radius: 5px; color: #60a5fa; cursor: pointer;">
                            🔄 重试
                        </button>
                    </div>
                </div>
            `).removeClass('hidden');
            console.error('❌ MVU框架加载超时');
            diagnoseMvuAvailability();
        }
        return;
    }

    if (typeof Mvu === 'undefined' && window.parent && typeof window.parent.Mvu !== 'undefined') {
        window.Mvu = window.parent.Mvu;
        console.log('✅ 已从父窗口引用MVU');
    }

    console.log('✅ MVU框架已就绪');

    // 智能获取应该显示的数据
    let targetMessageId = 'latest';
    if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
        let currentId = getLastMessageId();

        while (currentId >= 0) {
            const message = getChatMessages(currentId).at(-1);
            if (message && message.role !== 'user') {
                targetMessageId = currentId;
                if (currentId !== getLastMessageId()) {
                    console.log(`📝 向上查找到第 ${currentId} 层的AI消息`);
                }
                break;
            }
            currentId--;
        }

        if (currentId < 0) {
            targetMessageId = 'latest';
            console.warn('⚠️ 没有找到AI消息，使用最后一层');
        }
    }

    const data = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

    if (!data || !data.stat_data) {
        console.warn('⚠️ MVU数据为空，尝试自动修复...');

        if (retryCount === 0) {
            console.log('🔧 自动触发变量重新处理...');
            $('#village-status-top').html(`
