                    </button>
                </div>
            </div>
        `).removeClass('hidden');

        // 不要移除旧卡片，保留已有内容
        return;
    }

    const statData = data.stat_data;
    console.log('📊 stat_data字段:', Object.keys(statData));

    // 隐藏顶部加载提示
    $('#village-status-top').addClass('hidden');

    // 生成卡片HTML
    const cardHtml = generateVillageCard(statData);

    // 保存旧卡片的收起状态
    const wasCollapsed = $('.village-card-wrapper').hasClass('collapsed');

    // 只有在成功生成新卡片后才移除旧卡片
    $('.village-card-wrapper').remove();

    // 在顶部状态区域后追加新卡片
    $('#village-card-status').append(cardHtml);

    // 如果之前是收起状态，恢复收起状态
    if (wasCollapsed) {
        $('.village-card-wrapper').addClass('collapsed');
        $('.village-card-collapse-btn span').text('📍');
        $('.village-card-collapse-btn').attr('title', '展开');
        console.log('✅ 已恢复收起状态');
    }

    // 初始化样式和功能
    initializeCardStyles();
    setupEventDelegation();

    // 延迟初始化拖拽功能
    setTimeout(() => {
        const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
        const container = $container[0];

        if (!container) {
            console.error('❌ 容器不存在，无法初始化拖拽');
        } else if (container.dataset.dragInitialized !== 'true') {
            try {
                initializeDragFeature();
                container.dataset.dragInitialized = 'true';
                console.log('✅ 拖拽功能已启用');
            } catch (error) {
                console.error('❌ 拖拽初始化失败:', error);
            }
        }
    }, 300);

    console.log('✅ 数据显示完成');
}

// ========== 生成圣女卡片 ==========
function generateVillageCard(statData) {
    const generators = {
        worldInfo: generateWorldInfo,
        myInfo: generateMyInfo,
        blackMarket: generateBlackMarket,
        items: generateItems,
        specialPrayers: generateSpecialPrayers,
        characterBonds: generateCharacterBonds,
        map: generateMap,
        plot: generatePlot
    };

    // 生成Tab标签
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    Object.entries(SAINTESS_CONFIG.fields).forEach(([key, config]) => {
        const dataFieldName = config.name;
        const icon = config.icon || '📋';
        const generator = generators[key];

        if (!generator) {
            console.warn(`⚠️ 没有找到"${key}"的生成器`);
            return;
        }

        const fieldData = statData[dataFieldName] || {};
        if (!statData[dataFieldName]) {
            console.warn(`⚠️ 没有找到"${dataFieldName}"数据，将显示空状态`);
        }

        // 生成Tab标签
        tabsHtml += `
            <div class="village-tab ${firstTab ? 'active' : ''}" data-tab="${key}">
                <span>${icon}</span>
                <span>${dataFieldName}</span>
            </div>
        `;

        // 生成Tab内容
        let panelContent;
        try {
            panelContent = generator(fieldData);
        } catch (error) {
            console.error(`❌ 生成"${dataFieldName}"面板时出错:`, error);
            panelContent = `
                <div class="section">
                    <div class="section-title" style="color: #ef4444;">⚠️ ${dataFieldName}</div>
                    <div class="section-content">
                        <div style="padding: 20px; text-align: center; color: #9ca3af;">
                            <p>生成面板时出错</p>
                            <p style="font-size: 12px; margin-top: 10px; color: #ef4444;">${error.message}</p>
                        </div>
                    </div>
                </div>
            `;
        }

        panelsHtml += `
            <div class="village-panel-wrapper ${firstTab ? 'active' : ''}" data-tab="${key}">
                ${panelContent}
            </div>
        `;

        firstTab = false;
    });

    return `
    <div class="village-card-wrapper" id="village-main-card">
        <div class="village-card-3d">
            <div class="village-card-main">
                <div class="village-card-content-inner">
                    <!-- 控制按钮 -->
                    <div class="village-card-control-buttons">
                        <div class="village-card-control-left">
                            <button class="village-card-collapse-btn" data-action="toggle-collapse" title="收起/展开">
                                <span>📌</span>
                            </button>
                        </div>
                        <div class="village-card-control-right">
                            <button class="village-card-style-btn" data-action="toggle-style" title="切换样式">
                                <span>🎨</span>
                            </button>
                            <button class="village-card-refresh-btn" data-action="refresh" title="刷新数据">
                                <span class="icon">🔄</span>
                            </button>
                        </div>
                    </div>

                    <!-- Tab标签栏 -->
                    <div class="village-tabs">
                        ${tabsHtml}
                    </div>

                    <!-- Tab内容区域 -->
                    <div class="village-tab-content">
                        ${panelsHtml}
                    </div>
                </div>
            </div>
        </div>
    </div>
    `;
}

// ==================== 辅助函数 ====================
function safeGetArray(data, defaultValue = []) {
    try {
        if (Array.isArray(data)) {
            return data.filter(item => item !== '$__META_EXTENSIBLE__$');
        } else if (data && typeof data === 'string') {
            return [data];
        } else if (data === null || data === undefined) {
            return defaultValue;
        } else {
            console.warn('⚠️ 数据不是数组，尝试转换:', data);
            return defaultValue;
        }
    } catch (e) {
        console.warn('⚠️ 处理数组数据时出错:', e);
        return defaultValue;
    }
}

// ========== 圣洁值和堕落值颜色计算 ==========
function getHolinessColor(holiness) {
    if (holiness >= 900) return '#60d5ff'; // 明亮的圣光蓝
    if (holiness >= 700) return '#82e0ff'; // 浅蓝
    if (holiness >= 500) return '#a3ebff'; // 更浅的蓝
    if (holiness >= 300) return '#ffb84d'; // 橙色（警告）
    if (holiness >= 100) return '#ff8c42'; // 深橙（危险）
    return '#ff4d4d'; // 红色（堕落）
}

function getCorruptionColor(corruption) {
    if (corruption >= 800) return '#8b00ff'; // 深紫（完全堕落）
    if (corruption >= 600) return '#a020f0'; // 紫色
    if (corruption >= 400) return '#c860ff'; // 淡紫
    if (corruption >= 200) return '#e090ff'; // 更淡的紫
    if (corruption >= 100) return '#f0c0ff'; // 非常淡的紫
    return '#e8e8e8'; // 灰白（纯洁）
}

function getHolinessStatus(holiness) {
    if (holiness >= 900) return '圣洁无瑕';
    if (holiness >= 700) return '纯洁';
    if (holiness >= 500) return '轻微动摇';
    if (holiness >= 300) return '信仰衰退';
    if (holiness >= 100) return '濒临堕落';
    return '已经堕落';
}

function getCorruptionStatus(corruption) {
    if (corruption >= 800) return '完全堕落（不可逆）';
    if (corruption >= 600) return '淫荡成性';
    if (corruption >= 400) return '欲望深重';
    if (corruption >= 200) return '身体觉醒';
    if (corruption >= 100) return '初尝禁果';
    return '纯洁无知';
}


