            </div>
        </div>
        `;
    }

    const items = Object.keys(itemsData.道具列表).filter(k => k !== '$meta');

    if (items.length === 0) {
        return `
        <div class="section">
            <div class="section-title">🎁 道具</div>
            <div class="section-content">
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
