            ` : ''}

            <!-- 详细信息（可折叠） -->
            <div class="bond-details">
            <!-- 心理态度 -->
            <div style="margin-top: 10px; padding: 10px; background: rgba(255, 107, 129, 0.1); border-radius: 6px;">
                <div style="color: #ff6b81; font-size: 12px; font-weight: 600; text-align: center;">对艾莉娅: ${attitude}</div>
                </div>

            <!-- 外貌特征 -->
            <div style="margin-top: 10px;">
                <div style="color: rgba(255, 255, 255, 0.5); font-size: 11px; margin-bottom: 6px;">外貌特征</div>
                <div class="bond-stats">
                    <div><span style="color: #9ca3af;">身高:</span> ${height}</div>
