                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">👋 第一次见面:</span> ${meetings.join('; ')}</div>`);
                            }
                        }
                        if (records.重要事件?.[0]) {
                            const events = safeGetArray(records.重要事件[0]);
                            if (events.length > 0) {
                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">⭐ 重要事件:</span> ${events.join('; ')}</div>`);
                            }
                        }
                        if (records.关系变化?.[0]) {
                            const changes = safeGetArray(records.关系变化[0]);
                            if (changes.length > 0) {
                                items.push(`<div style="font-size: 11px; padding: 4px 8px; background: rgba(255, 255, 255, 0.05); border-radius: 4px;"><span style="color: #9ca3af;">💕 关系变化:</span> ${changes.join('; ')}</div>`);
                            }
