    }).join('');

    return `
    <div class="section">
        <div class="section-title">💖 人物羁绊 (${characters.length}人)</div>
        <div class="section-content">
            <div class="bond-list">
                ${charactersHtml}
            </div>
        </div>
    </div>
    `;
}

// ========== 生成地图系统 ==========
function generateMap(map) {
    let envHtml = '';
    if (map.周边环境) {
        const places = Object.keys(map.周边环境).filter(k => k !== '$meta');
        if (places.length > 0) {
            envHtml = places.map(placeName => {
                const place = map.周边环境[placeName];
                const distance = place.距离?.[0] || 0;
                const desc = place.描述?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${placeName}</div>
                    <div style="font-size: 10px;">${distance}米</div>
                    ${desc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    let locationsHtml = '';
    if (map.可探索地点) {
        const locations = Object.keys(map.可探索地点).filter(k => k !== '$meta');
        if (locations.length > 0) {
            locationsHtml = locations.map(locName => {
                const loc = map.可探索地点[locName];
                const locDesc = loc.描述?.[0] || '';
                const locStatus = loc.状态?.[0] || '';
                const locType = loc.类型?.[0] || '';

                return `
                <div class="map-location ${locStatus === '当前位置' ? 'active' : ''}">
                    <div class="location-name">${locName}</div>
                    ${locType ? `<div style="font-size: 10px; color: #9ca3af;">${locType}</div>` : ''}
                    ${locStatus ? `<div style="color: #4ade80; font-size: 10px;">(${locStatus})</div>` : ''}
                    ${locDesc ? `<div style="font-size: 10px; color: #9ca3af; margin-top: 2px;">${locDesc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    return `
