// ==================== MVU框架检测 ====================
function diagnoseMvuAvailability() {
    console.log('🔍 MVU框架诊断:');
    console.log('  - typeof Mvu:', typeof Mvu);
    console.log('  - typeof window.Mvu:', typeof window.Mvu);

    if (window.self !== window.top && window.parent) {
        try {
            console.log('  - 父窗口 typeof Mvu:', typeof window.parent.Mvu);
        } catch (e) {
            console.log('  - 无法访问父窗口Mvu:', e.message);
        }
    }
}

function waitForMvu(callback, maxAttempts = 20) {
    let attempts = 0;

    const checkMvu = () => {
        attempts++;

        const mvuExists = typeof Mvu !== 'undefined' ||
                         typeof window.Mvu !== 'undefined' ||
                         (window.parent && typeof window.parent.Mvu !== 'undefined');

        if (mvuExists) {
            console.log('✅ MVU框架已检测到');

            if (typeof Mvu === 'undefined' && window.parent && typeof window.parent.Mvu !== 'undefined') {
                window.Mvu = window.parent.Mvu;
                console.log('✅ 已从父窗口引用MVU');
            }

            callback();
        } else if (attempts < maxAttempts) {
            if (attempts === 1 || attempts % 5 === 0) {
                console.log(`⏳ 等待MVU框架... (${attempts}/${maxAttempts})`);
            }
            setTimeout(checkMvu, 1000);
        } else {
            console.warn('⚠️ MVU框架预检测超时，继续初始化');
            diagnoseMvuAvailability();
            callback();
        }
    };

    checkMvu();
}

// ==================== 初始化函数 ====================
function initializeVillageCardStatus() {
    console.log('🚀 开始启动卡片状态栏');

    try {
        // 清理可能存在的旧容器
        if (window.top && window.top.document !== document) {
            $(window.top.document).find('#village-card-status').remove();
            $(window.top.document).find('#village-card-styles').remove();
        }
        $('#village-card-status').remove();
        $('#village-card-styles').remove();

        $('head').append(styles);
        console.log('✅ 样式已注入');

        const container = $('<div>', {
            id: 'village-card-status',
            class: 'village-card-container'
        });

        // 创建顶部状态区域
        const statusTop = $('<div>', {
            id: 'village-status-top',
            class: 'village-status-top',
            html: '<p style="color: #60a5fa;">⏳ 正在加载数据...</p>'
        });

        container.append(statusTop);
        $('body').prepend(container);
        console.log('✅ 容器已创建');

        setTimeout(() => {
            loadAndDisplay();
        }, 2000);

        console.log('🎉 卡片状态栏初始化完成！');

    } catch (error) {
        console.error('❌ 初始化状态栏时出错:', error);
        console.error('错误堆栈:', error.stack);

        if (typeof toastr !== 'undefined') {
            toastr.error('状态栏初始化失败：' + error.message);
        } else {
            alert('状态栏初始化失败：' + error.message + '\n\n详情请查看控制台');
        }
    }
}

