// ========== 生成世界信息 ==========
function generateWorldInfo(worldInfo) {
    const time = worldInfo.时间?.当前时间?.[0] || '未知';
    const location = worldInfo.位置?.详细位置?.[0] || '未知';
    const companions = safeGetArray(worldInfo.位置?.同行人员?.[0]);
    const indoorTemp = worldInfo.环境?.室内温度?.[0] || 25;
    const outdoorTemp = worldInfo.环境?.室外温度?.[0] || 28;
    const weather = worldInfo.环境?.天气?.[0] || '未知';

    // 财务
    const savings = worldInfo.财务?.存款?.[0] || 0;

