// ========== 生成黑市 ==========
function generateBlackMarket(market) {
    if (!market || !market.可用服务) {
        return `
        <div class="section">
            <div class="section-title">🔮 黑市</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无服务数据</div>
            </div>
        </div>
        `;
    }

    const services = Object.keys(market.可用服务).filter(k => k !== '$meta');
    const purchasedServices = safeGetArray(market.已购买服务?.[0]);

    if (services.length === 0) {
        return `
        <div class="section">
            <div class="section-title">🔮 黑市</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无可用服务</div>
            </div>
        </div>
        `;
    }

    const servicesHtml = services.map(key => {
        const service = market.可用服务[key];
        const serviceName = service.服务名称?.[0] || key;
        const price = service.价格?.[0] || 0;
        const effect = service.效果?.[0] || '';
        const description = service.说明?.[0] || '';
        const risk = service.风险?.[0] || '';

        // 检查是否已购买
        const isPurchased = purchasedServices.some(p => p.includes(serviceName) || p.includes(key));

        return `
        <div class="service-item ${isPurchased ? 'purchased' : ''}" style="border-color: rgba(139, 92, 246, 0.5);">
            <div class="service-header">
                <div class="service-name" style="color: #8b5cf6;">${serviceName}</div>
                <div class="service-price" style="background: linear-gradient(135deg, rgba(139, 92, 246, 0.3) 0%, rgba(124, 58, 237, 0.3) 100%); color: #a78bfa;">💰${price}</div>
            </div>

            ${effect ? `
            <div class="service-effect" style="background: rgba(139, 92, 246, 0.15); color: #c4b5fd;">
                ⚡ ${effect}
            </div>
            ` : ''}

            ${description ? `
            <div class="service-description" style="margin-top: 8px;">
                ${description}
            </div>
            ` : ''}

            ${risk ? `
            <div style="margin-top: 8px; padding: 6px 10px; background: rgba(239, 68, 68, 0.1); border-radius: 6px; border-left: 2px solid rgba(239, 68, 68, 0.5);">
                <div style="color: #ef4444; font-size: 11px; font-weight: 600;">⚠️ 风险</div>
                <div style="color: rgba(255, 255, 255, 0.7); font-size: 10px; margin-top: 4px;">${risk}</div>
            </div>
            ` : ''}

            ${isPurchased ? `
            <div style="margin-top: 8px; padding: 6px 10px; background: rgba(76, 175, 80, 0.15); border-radius: 6px; text-align: center; color: #4caf50; font-size: 11px; font-weight: 500;">
                ✅ 已购买
            </div>
            ` : ''}
        </div>
        `;
    }).join('');

    return `
    <div class="section">
        <div class="section-title">🔮 黑市 (可用: ${services.length} | 已购: ${purchasedServices.length})</div>
        <div class="section-content">
            <div style="margin-bottom: 12px; padding: 10px; background: rgba(139, 92, 246, 0.1); border-radius: 8px; border-left: 3px solid rgba(139, 92, 246, 0.5);">
                <div style="color: #a78bfa; font-size: 12px; font-weight: 600; margin-bottom: 6px;">🔮 警告</div>
                <div style="font-size: 11px; color: rgba(255, 255, 255, 0.7); line-height: 1.5;">
                    这里贩卖的是禁忌之物，使用后会影响你的圣洁值和堕落值。一旦堕落值超过800，就再也无法回头...
                </div>
            </div>

            ${purchasedServices.length > 0 ? `
            <div style="margin-bottom: 12px; padding: 10px; background: rgba(76, 175, 80, 0.1); border-radius: 8px; border-left: 3px solid rgba(76, 175, 80, 0.5);">
                <div style="color: #4caf50; font-size: 12px; font-weight: 600; margin-bottom: 6px;">✅ 已购买的服务 (${purchasedServices.length})</div>
                <div style="font-size: 11px; color: rgba(255, 255, 255, 0.8);">
                    ${purchasedServices.join(' • ')}
                </div>
            </div>
            ` : ''}

            <div class="service-grid">
                ${servicesHtml}
            </div>
        </div>
    </div>
    `;
}

