// ========== 生成特殊祈福 ==========
function generateSpecialPrayers(prayers) {
    // 处理空数据或未初始化的情况
    if (!prayers || !prayers.祈福列表) {
        return `
        <div class="section">
            <div class="section-title">✝️ 特殊祈福 (0 | 0)</div>
            <div class="section-content">
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 16px; opacity: 0.3;">✝️</div>
                    <div style="font-size: 16px; margin-bottom: 8px;">暂无祈福请求</div>
                    <div style="font-size: 12px; color: #6b7280;">等待教会或贵族的祈福请求...</div>
                </div>
            </div>
        </div>
        `;
    }

    const prayerList = Object.keys(prayers.祈福列表).filter(k => k !== '$meta');
    if (prayerList.length === 0) {
        const stats = prayers.祈福统计 || {};
        const totalPrayers = stats.总祈福数?.[0] || 0;
        const completedPrayers = stats.已完成数?.[0] || 0;
        const totalIncome = stats.总收入?.[0] || 0;

        return `
        <div class="section">
            <div class="section-title">✝️ 特殊祈福 (${totalPrayers - completedPrayers} | ${completedPrayers})</div>
            <div class="section-content">
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 16px; opacity: 0.3;">✝️</div>
                    <div style="font-size: 16px; margin-bottom: 8px;">暂无活动祈福</div>
                    <div style="font-size: 12px; color: #6b7280;">
                        ${totalPrayers > 0 ? `历史祈福: ${totalPrayers} 次 | 总收入: 💰${totalIncome}金币` : '等待第一个祈福请求...'}
                    </div>
                </div>
            </div>
        </div>
        `;
    }

    // 分类祈福：未接受、进行中和已完成
    const unacceptedPrayers = [];
    const pendingPrayers = [];
    const completedPrayers = [];

    prayerList.forEach(key => {
        const prayer = prayers.祈福列表[key];
        const status = prayer.委托状态?.[0] || '未接受';
        if (status === '已完成') {
            completedPrayers.push({ key, prayer });
        } else if (status === '进行中') {
            pendingPrayers.push({ key, prayer });
        } else {
            unacceptedPrayers.push({ key, prayer });
        }
    });

    const generatePrayerHtml = ({ key, prayer }) => {
        const clientName = prayer.委托人姓名?.[0] || key;
        const age = prayer.年龄?.[0] || '?';
        const identity = prayer.身份?.[0] || '未知';
        const surfaceRequest = prayer.表面需求?.[0] || '';
        const hint = prayer.暗示内容?.[0] || '';
        const price = prayer.报酬?.[0] || 0;
        const status = prayer.委托状态?.[0] || '未接受';
        const holinessImpact = prayer.圣洁影响?.[0] || 0;
        const corruptionImpact = prayer.堕落影响?.[0] || 0;

        // 状态判断
        const isCompleted = status === '已完成';
        const isPending = status === '进行中';
        const isUnaccepted = status === '未接受' || status === '待接受' || !status || status === '';

        // 根据影响值确定危险程度颜色
        const dangerLevel = Math.abs(holinessImpact) + corruptionImpact;
        let dangerColor = '#4ade80'; // 绿色（安全）
        if (dangerLevel > 200) dangerColor = '#ef4444'; // 红色（极危险）
        else if (dangerLevel > 100) dangerColor = '#fb923c'; // 橙色（危险）
        else if (dangerLevel > 50) dangerColor = '#fbbf24'; // 黄色（警告）

        return `
        <div class="order-item ${isCompleted ? 'completed' : ''}" style="border-left-color: ${dangerColor};">
            <div class="order-header">
                <div class="order-client-name">${clientName}</div>
                <div class="order-status ${isCompleted ? 'completed' : isPending ? 'pending' : 'unaccepted'}">
                    ${isCompleted ? '✅ 已完成' : isPending ? '⏳ 进行中' : '📋 未接受'}
                </div>
            </div>

            <div class="order-info">
                <div><span style="color: #9ca3af;">年龄:</span> ${age}岁</div>
                <div><span style="color: #9ca3af;">身份:</span> ${identity}</div>
                </div>

            ${surfaceRequest ? `
            <div style="margin-top: 10px; padding: 8px 10px; background: rgba(96, 165, 250, 0.1); border-radius: 6px; border-left: 2px solid rgba(96, 165, 250, 0.5);">
                <div style="color: #60a5fa; font-size: 11px; font-weight: 600; margin-bottom: 4px;">📜 祈福需求</div>
                <div style="color: rgba(255, 255, 255, 0.8); font-size: 12px; line-height: 1.5;">${surfaceRequest}</div>
            </div>
            ` : ''}

            ${hint ? `
            <div style="margin-top: 8px; padding: 8px 10px; background: rgba(251, 191, 36, 0.1); border-radius: 6px; border-left: 2px solid rgba(251, 191, 36, 0.5);">
                <div style="color: #fbbf24; font-size: 11px; font-weight: 600; margin-bottom: 4px;">💡 特殊要求</div>
                <div style="color: rgba(255, 255, 255, 0.7); font-size: 11px; line-height: 1.5; font-style: italic;">${hint}</div>
