                    ${corruptionImpact !== 0 ? `<div style="color: ${corruptionImpact > 0 ? '#a020f0' : '#4ade80'};">😈 堕落值 ${corruptionImpact > 0 ? '+' : ''}${corruptionImpact}</div>` : ''}
