// ========== 生成人物羁绊 ==========
function generateCharacterBonds(bonds) {
    const characters = Object.keys(bonds).filter(k => k !== '$meta');

    if (characters.length === 0) {
        return `
        <div class="section">
            <div class="section-title">💖 人物羁绊</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">
                    暂无人物羁绊记录
                </div>
            </div>
        </div>
        `;
    }

    const charactersHtml = characters.map(charKey => {
        const beauty = bonds[charKey];
        const name = beauty.基础信息?.姓名?.[0] || charKey;
        const age = beauty.基础信息?.年龄?.[0] || '-';
        const identity = beauty.基础信息?.身份?.[0] || '-';
        const heartbeat = beauty.心跳?.[0] || 80;
        const thought = beauty.心理状态?.当前所想?.[0] || '';
        const attitude = beauty.心理状态?.对艾莉娅的态度?.[0] || '陌生';

        // 外貌信息
        const appearance = beauty.基础信息?.外貌 || {};
        const height = appearance.身高?.[0] || '-';
        const hairColor = appearance.发色?.[0] || '-';
        const hairStyle = appearance.发型?.[0] || '-';
        const eyeColor = appearance.瞳色?.[0] || '-';
        const bodyType = appearance.体型?.[0] || '-';

        // 服装信息
        const clothing = beauty.服装 || {};
        const top = clothing.上衣?.[0] || '未知';
        const bottom = clothing.下装?.[0] || '未知';
        const accessories = clothing.配饰?.[0] || '无';

        // 性癖
        const fetishes = safeGetArray(beauty.性癖?.[0]);

        // 计算心电图动画速度
        const animationDuration = ((60000 / heartbeat) * 2).toFixed(0);

        return `
        <div class="bond-item collapsed">
            <div class="bond-name">${name} (${age}岁)</div>
            <div style="font-size: 12px; color: #9ca3af; margin-bottom: 8px; display: flex; align-items: center; gap: 8px;">
