                    <polyline style="fill: none; stroke: rgba(255, 77, 80, 0.2); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;" points="0 47.907, 28 47.907, 32 23.907, 36 59.907, 40 51.907, 44 47.907, 80 47.907"></polyline>
                    <polyline style="fill: none; stroke: #ff4d50; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 48, 144; stroke-dashoffset: 192; animation: heartbeat-dash-anim ${animationDuration}ms linear infinite;" points="0 47.907, 28 47.907, 32 23.907, 36 59.907, 40 51.907, 44 47.907, 80 47.907"></polyline>
                </svg>
                <span>${heartbeat} BPM | ${identity}</span>
            </div>

            ${thought ? `
            <div style="padding: 8px; background: rgba(255, 255, 255, 0.05); border-radius: 6px; margin-bottom: 8px; font-size: 12px; font-style: italic;">
                💭 ${thought}
            </div>
            ` : ''}

            <!-- 详细信息（可折叠） -->
            <div class="bond-details">
            <!-- 心理态度 -->
            <div style="margin-top: 10px; padding: 10px; background: rgba(255, 107, 129, 0.1); border-radius: 6px;">
                <div style="color: #ff6b81; font-size: 12px; font-weight: 600; text-align: center;">对艾莉娅: ${attitude}</div>
                </div>

            <!-- 外貌特征 -->
            <div style="margin-top: 10px;">
                <div style="color: rgba(255, 255, 255, 0.5); font-size: 11px; margin-bottom: 6px;">外貌特征</div>
                <div class="bond-stats">
                    <div><span style="color: #9ca3af;">身高:</span> ${height}</div>
                    <div><span style="color: #9ca3af;">体型:</span> ${bodyType}</div>
                    <div><span style="color: #9ca3af;">发色:</span> ${hairColor}</div>
                    <div><span style="color: #9ca3af;">发型:</span> ${hairStyle}</div>
                    <div><span style="color: #9ca3af;">瞳色:</span> ${eyeColor}</div>
                </div>
            </div>

            <!-- 当前着装 -->
            <div style="margin-top: 10px;">
                <div style="color: rgba(255, 255, 255, 0.5); font-size: 11px; margin-bottom: 6px;">当前着装</div>
                <div class="bond-stats">
                    ${top !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">上衣:</span> ${top}</div>` : ''}
                    ${bottom !== '未知' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">下装:</span> ${bottom}</div>` : ''}
                    ${accessories !== '无' ? `<div style="font-size: 11px;"><span style="color: #9ca3af;">配饰:</span> ${accessories}</div>` : ''}
