            </div><!-- 关闭 bond-details -->
        </div>
        `;
    }).join('');

    return `
    <div class="section">
        <div class="section-title">💖 人物羁绊 (${characters.length}人)</div>
        <div class="section-content">
            <div class="bond-list">
                ${charactersHtml}
            </div>
        </div>
    </div>
    `;
