// ========== 设置事件委托 ==========
let eventDelegationSetup = false; // 标记是否已设置事件委托

function cleanupEventDelegation() {
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
    if ($container.length) {
        $container.off('.buttons .tabs .bonds .prayers');
        console.log('🧹 已清理事件委托');
    }
    eventDelegationSetup = false;
}

function setupEventDelegation() {
    if (eventDelegationSetup) {
        console.log('⏭️ 事件委托已存在，跳过重复设置');
        return;
    }

    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');

    // 使用事件委托绑定所有按钮点击事件（使用命名空间避免冲突）
    $container.on('click.buttons', '[data-action]', async function(e) {
        // 不阻止默认行为和冒泡，让点击自然发生

        const $btn = $(this);
        const action = $btn.data('action');

        console.log('🔔 按钮被点击:', action);

        if ($btn.prop('disabled')) {
            console.warn('⚠️ 按钮已禁用，忽略点击');
            return;
        }

        try {
            switch(action) {
                case 'toggle-style':
                    console.log('🎨 切换样式...');
                    toggleCardStyle();
                    break;

                case 'refresh':
                    console.log('🔄 开始刷新数据...');
                    $btn.addClass('refreshing').prop('disabled', true);

                    try {
                        console.log('🔧 触发重新处理变量...');
                        await reprocessCurrentMessageVariables();

                        console.log('⏳ 等待变量处理完成...');
                        await new Promise(resolve => setTimeout(resolve, 500));

                        console.log('🔄 刷新显示数据...');
                        // 不要先清除，让loadAndDisplay内部处理替换
                        loadAndDisplay();

                        console.log('✅ 刷新完成');
                    } finally {
                        setTimeout(() => {
                            $btn.removeClass('refreshing').prop('disabled', false);
                        }, 500);
                    }
                    break;

                case 'toggle-collapse':
                    console.log('📌 切换收起状态');
                    const $cardWrapper = $('.village-card-wrapper');
                    $cardWrapper.toggleClass('collapsed');

                    const isCollapsed = $cardWrapper.hasClass('collapsed');
                    $btn.find('span').text(isCollapsed ? '📍' : '📌');
                    $btn.attr('title', isCollapsed ? '展开' : '收起');
                    break;

                default:
                    console.warn('⚠️ 未知的操作:', action);
            }
        } catch (error) {
            console.error('❌ 操作失败:', error);
            if (typeof toastr !== 'undefined') {
                toastr.error('操作失败：' + error.message);
            }
        }
    });

    // Tab切换事件
    $container.on('click.tabs', '.village-tab', function(e) {
        const $tab = $(this);
        const tabKey = $tab.data('tab');

        console.log('📑 切换到Tab:', tabKey);

        // 切换Tab激活状态
        $('.village-tab').removeClass('active');
        $tab.addClass('active');

        // 切换面板显示
        $('.village-panel-wrapper').removeClass('active');
        $(`.village-panel-wrapper[data-tab="${tabKey}"]`).addClass('active');
    });

    // 人物羁绊展开/收起事件
    $container.on('click.bonds', '.bond-item', function(e) {
        const $bondItem = $(this);
        $bondItem.toggleClass('collapsed');

        const isCollapsed = $bondItem.hasClass('collapsed');
        console.log('💖 人物羁绊卡片', isCollapsed ? '收起' : '展开');
    });

    // 祈福接受按钮点击事件
    $container.on('click.prayers', '.prayer-accept-btn', async function(e) {
        e.preventDefault();
        e.stopPropagation();

        const $btn = $(this);
        const prayerKey = $btn.data('prayer-key');
        const clientName = $btn.data('client-name');

        console.log('✝️ 祈福接受按钮被点击:', { prayerKey, clientName });

        // 禁用按钮防止重复点击
        $btn.prop('disabled', true);

        try {
            // 检查 triggerSlash 函数是否存在
            if (typeof triggerSlash !== 'function') {
                console.error('[Accept Prayer] triggerSlash 函数不可用');
                alert('操作失败：系统函数不可用');
                $btn.prop('disabled', false);
                return;
            }

            // 发送接受祈福的消息
            const message = `<Request:Meta-instructions：接下来你要，我接受了${clientName}的祈福请求（祈福编号：${prayerKey}），注意更新委托状态为"进行中"！> 接受祈福`;
            await triggerSlash(`/send ${message}`);
            await triggerSlash('/trigger');

            console.log('[Accept Prayer] 接受祈福请求已发送');

            // 显示提示
            if (typeof toastr !== 'undefined') {
                toastr.success(`已接受 ${clientName} 的祈福请求`);
            } else {
                alert(`已接受 ${clientName} 的祈福请求`);
            }

            // 2秒后恢复按钮
                setTimeout(() => {
                    $btn.prop('disabled', false);
                }, 2000);
        } catch (error) {
            console.error('[Accept Prayer] 接受祈福失败:', error);
            if (typeof toastr !== 'undefined') {
                toastr.error('接受祈福失败：' + error.message);
            } else {
                alert('接受祈福失败：' + error.message);
            }
            $btn.prop('disabled', false);
        }
    });

    eventDelegationSetup = true;
    console.log('✅ 事件委托已设置（仅一次）');
}

// ========== 重新处理当前消息变量 ==========
async function reprocessCurrentMessageVariables() {
    try {
        if (typeof getLastMessageId !== 'function' || typeof getChatMessages !== 'function') {
            console.warn('⚠️ 必要函数不可用');
            return;
        }

        let messageId = getLastMessageId();

        if (messageId < 0) {
            console.warn('⚠️ 没有有效的消息ID');
            return;
        }

        let foundAiMessage = false;
        while (messageId >= 0) {
            const message = getChatMessages(messageId).at(-1);
            if (message && message.role !== 'user') {
                foundAiMessage = true;
                if (messageId !== getLastMessageId()) {
                    console.log(`📝 向上查找到第 ${messageId} 层的AI消息，重新处理该层`);
                }
                break;
            }
            messageId--;
        }

