function handleVillageMessageReceived() {
    console.log('📨 收到 MESSAGE_RECEIVED 事件，刷新状态栏数据...');
    setTimeout(() => {
        try {
            const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
            if ($container.length > 0) {
                // 不要先清除，让loadAndDisplay内部处理替换
                loadAndDisplay();
            } else {
                console.warn('⚠️ 状态栏未初始化，跳过数据更新');
