{
  "世界名称": "艾瑟利亚大陆",
  "世界概述": {
    "背景": "艾瑟利亚大陆是一片被圣光与黑暗交织笼罩的土地。在这里，光辉教会以神的名义统治着人类的灵魂，而各大王国则掌控着世俗的权力。表面上，教会是纯洁与信仰的象征，但在华丽的圣殿与庄严的祷告声背后，隐藏着贵族与神职人员之间不为人知的欲望纽带。",
    "时代特征": "这是一个神权与王权共治的时代，魔物在大陆边缘肆虐，而人类内部却被腐化与欲望侵蚀。教会垄断着对'神迹'的解释权，而贵族们则通过献祭、贡品和肉体来换取教会的庇护与祝福。",
    "核心主题": "信仰的虚伪、权力的腐化、欲望的纠葛、纯洁与堕落的边界"
  },

  "王国体系": {
    "主要王国": "卢瑟兰王国",
    "王都": "圣辉之城·瓦尔登",
    "统治者": "雷昂纳德三世",
    "政治结构": {
      "国王": "名义上的最高统治者，但实际权力受制于教会",
      "贵族议会": "由公爵、侯爵、伯爵组成，掌控军队和土地",
      "教廷使节": "驻扎在王宫的教会代表，拥有否决权",
      "隐秘关系": "贵族为了获得教会的祝福（提升土地产量、祈求战争胜利、治疗疾病），需要向教会献上'特殊贡品'——包括金钱、圣物、以及年轻的男女。教会高层与贵族之间形成了一个秘密的'圣约网络'，在这个网络中，性与权力成为交易的货币。"
    },
    "社会阶层": {
      "王族与高级贵族": "拥有与大主教直接交易的权力，可获得最高级别的'圣礼'",
      "中低层贵族": "通过向地方教堂献上'侍奉者'来获取庇护",
      "平民": "被蒙在鼓里，虔诚地信奉着教会的教义",
      "奴隶与罪人": "最底层，常被用作魔物实验或秘密仪式的祭品"
    }
  },

  "光辉教会": {
    "教会名称": "圣光永恒教会",
    "至高神祇": "永恒之光·艾莉西亚女神",
    "教义表面": "宣扬纯洁、禁欲、奉献、博爱，要求信徒远离肉欲，将身心献给女神",
    "教义真相": "教会高层早已将教义扭曲，他们认为'通过肉体的奉献来净化灵魂'是一种特殊的修行方式。贵族献上的男女会成为'圣洁侍奉者'，在秘密的仪式中与主教、大主教们进行所谓的'灵魂净化仪式'。",

    "教会等级": {
      "圣女": "教会的象征，表面上纯洁无瑕，实际上是教会最高层的禁脔",
      "大主教": "各大教区的最高领袖，掌控着'圣约网络'的核心",
      "主教": "管理地方教堂，是贵族与教会交易的直接对接人",
      "神父": "执行日常教务，部分知晓秘密，部分真心信仰",
      "修女": "教会的基层，负责照顾信徒、管理圣堂。年轻貌美的修女往往会被选中参与'特殊仪式'",
      "见习修女": "刚加入教会的少女，尚未完全了解教会的黑暗"
    },

    "秘密仪式": {
      "圣洁献祭仪式": "贵族将年轻男女献给教会，这些人会在秘密地下圣堂中接受'净化'——实际上是成为高层神职人员的性奴",
      "灵魂契约仪式": "贵族与主教之间的契约仪式，通过交换肉体来达成政治或经济协议",
      "赎罪仪式": "犯错的贵族或教会成员需通过'肉体赎罪'来换取宽恕",
      "晋升试炼": "年轻修女想要晋升，需要通过'纯洁测试'——实际上是被高层玩弄的过程"
    }
  },

  "魔物设定": {
    "魔物起源": "千年前，大陆发生了'暗裂事件'，深渊裂隙在边境地带打开，无数魔物涌入人类世界。教会宣称这是神对人类罪孽的惩罚，实际上是为了维持自己的统治地位。",

    "主要魔物类型": {
      "欲魔": {
        "特征": "拥有人形，异常美丽，通过诱惑人类获取精气",
        "能力": "精神控制、幻术、吸取生命力",
        "与教会的关系": "教会秘密捕捉低级欲魔，用于某些'特殊仪式'中，声称可以'以毒攻毒'来净化被魔物侵蚀的灵魂"
      },
      "暗影兽": {
        "特征": "无固定形态，潜伏在阴影中",
        "能力": "操控黑暗、吞噬恐惧",
        "威胁": "经常袭击边境村落，制造恐慌"
      },
      "堕落骑士": {
        "特征": "曾经的人类战士，被魔物侵蚀后变成的怪物",
        "能力": "保留生前的战斗技巧，但力量和残暴性大幅提升",
        "堕落原因": "有传言称，部分堕落骑士是因为发现了教会的秘密而被有意引导堕落"
      },
      "触手怪": {
        "特征": "从深渊裂隙中爬出的异形生物",
        "能力": "捕获猎物、注入腐化毒素",
        "用途": "教会秘密饲养少量触手怪，用于惩罚背叛者或进行极端的'净化仪式'"
      }
    },

    "魔物威胁": "魔物不定期地从边境侵入，教会派出'圣骑士'讨伐，但实际上教会故意控制魔物的威胁程度，既不完全剿灭（以维持教会的必要性），也不让其过度泛滥。"
  },

  "女主角设定": {
    "姓名": "艾莉娅·莫里斯",
    "年龄": "16岁",
    "身份": "圣辉之城大教堂的正式修女",
    "外貌": "银白色长发，碧蓝色眼眸，身材姣好，面容清纯而美丽，穿着标准的黑白修女服",

    "背景故事": {
      "出身": "来自王都贫民区的孤儿，8岁时被教会收养",
      "成长": "在教会学院长大，接受了严格的圣光教育，对女神有着虔诚的信仰",
      "现状": "目前在王都大教堂担任修女，负责照顾贫民、主持祷告、协助神父工作",
      "纯洁度": "至今仍保持着处女之身，是教会中少有的真正纯洁的修女",
      "未知真相": "她不知道教会的黑暗面，也不知道自己已经被大主教列为下一次'晋升试炼'的候选人——因为她的美貌和纯洁已经引起了多位贵族的注意"
    },

    "性格特征": {
      "虔诚": "深信女神的存在，认为信仰可以拯救一切",
      "善良": "关心贫苦百姓，经常用自己的口粮接济流浪儿童",
      "天真": "对教会的黑暗一无所知，相信所有神父和主教都是圣洁的",
      "坚韧": "在孤儿院长大的经历让她内心坚强",
      "隐藏的好奇": "对禁书和世俗的爱情故事有隐秘的兴趣"
    },

    "命运转折": "一个月后，王国最有权势的公爵——达米安·瓦尔特将向教会献上巨额捐款，要求教会为他进行'特殊祝福仪式'。大主教已经选中了艾莉娅作为这次仪式的'圣洁祭品'。她即将被卷入教会与贵族之间肮脏的交易之中，纯洁的信仰将面临最严峻的考验..."
  },

  "隐秘纽带体系": {
    "名称": "圣约之链",
    "运作方式": {
      "等级制": "根据贵族的爵位和献金数量，可以获得不同等级的'圣礼服务'",
      "人员来源": "年轻修女、见习修女、被贵族献上的平民少女、犯罪者的女儿",
      "地点": "大教堂地下的'净化圣堂'，只有高层才知道入口",
      "仪式流程": "以'圣光净化'为名，实际上是纵欲的狂欢",
      "保密措施": "参与者签订'灵魂契约'，泄密者会被处以火刑，名义上是'被魔物侵蚀'"
    },

    "交易内容": {
      "贵族献上": "金钱、圣物、年轻男女、政治支持",
      "教会提供": "土地祝福、战争祈福、疾病治疗、情报网络、以及'肉体服务'",
      "特殊服务": "某些高级贵族可以'租借'修女到府邸进行'家庭祈福'，实际上是合法的性奴役"
    },

    "受害者": "大多数年轻修女最终都会被卷入这个系统，她们被告知这是'侍奉神的特殊方式'，在精神控制和威胁下屈服。少数反抗者会被送到边境'对抗魔物'——实际上是被喂给了魔物或卖给了奴隶贩子。"
  },

  "世界危机": {
    "表面危机": "魔物入侵越来越频繁，边境村落不断沦陷",
    "深层危机": "教会的腐化已经到了无以复加的地步，真正虔诚的神职人员越来越少，'圣光'的力量正在减弱。有传言说，女神已经抛弃了这片大陆，因为她的信徒早已背叛了她的教义。",
    "未来预言": "古老的预言书中记载：'当纯洁者的眼泪滴落在圣坛，当黑暗吞噬最后的光明，艾瑟利亚将迎来终焉或重生。'艾莉娅的命运，或许就是这个预言的关键..."
  },

  "剧情发展方向": {
    "堕落线": "艾莉娅逐渐发现教会的真相，在威胁和诱惑下屈服，成为'圣约之链'的一环，最终堕落为贵族的玩物",
    "反抗线": "艾莉娅在发现真相后选择反抗，联合其他受害者和正义骑士，试图揭露教会的黑暗，但过程中会遭受残酷的折磨和考验",
    "救赎线": "艾莉娅虽然经历了黑暗，但始终保持信仰，最终获得真正的'女神之力'，净化腐化的教会，驱逐魔物",
    "共存线": "艾莉娅被迫接受现实，学会在黑暗中生存，利用规则保护自己和其他无辜者，成为'圣约之链'中特殊的存在"
  },

  "世界观核心": "这是一个表面圣洁、内里腐朽的世界。信仰被权力玷污，纯洁成为交易的筹码。艾莉娅的故事，是一个关于一个纯洁灵魂如何在肮脏的世界中挣扎、沉沦或升华的传奇。"
}

